const calls = [
  ["ROOT", {cmd:"git branch --show-current && git status --short && git status --branch --short && git log -1 --format='%H%n%s%n%b' && git rev-list --count origin/main..HEAD && git diff --name-status origin/main...HEAD && git diff --name-status HEAD", workdir:"/Users/flake/sources/misc/secman", yield_time_ms:1000, max_output_tokens:12000}],
  ["EXTENSIONS", {cmd:"find extensions -mindepth 1 -maxdepth 1 -type d -print | sort; for d in extensions/*/; do if [ -d \"$d/.git\" ]; then echo \"== $d\"; git -C \"$d\" branch --show-current; git -C \"$d\" status --short; fi; done", workdir:"/Users/flake/sources/misc/secman", yield_time_ms:1000, max_output_tokens:12000}],
  ["VERSIONS", {cmd:"grep -nE 'kotlin.jvm|kotlinVersion|micronautVersion|io.micronaut.application' build.gradle.kts; grep distributionUrl gradle/wrapper/gradle-wrapper.properties; grep -nE 'jvmToolchain|JavaVersion' src/backendng/build.gradle.kts src/cli/build.gradle.kts; grep -E '\"(astro|react|axios|typescript)\":' src/frontend/package.json; grep -nE 'picocli|aws|software.amazon' src/cli/build.gradle.kts | head; grep -nE '^go |^toolchain' src/relay/go.mod; rg -n 'image:\\s*mariadb' docker", workdir:"/Users/flake/sources/misc/secman", yield_time_ms:1000, max_output_tokens:12000}],
  ["COUNTS", {cmd:"wc -l -w CLAUDE.md docs/CHANGELOG.md; rg -n '^\\*Last updated:' CLAUDE.md; rg -n '^## Recent Changes|^- \\*\\*' CLAUDE.md; git log --follow --format='%h %ad %s' --date=short -5 -- CLAUDE.md", workdir:"/Users/flake/sources/misc/secman", yield_time_ms:1000, max_output_tokens:12000}]
];
const rs = await Promise.all(calls.map(async ([label,args]) => [label, await tools.exec_command(args)]));
for (const [label,r] of rs) { text(`===${label}===\n${r.output}`); }

const calls = [
  ["AUTH", {cmd:"rg -n \"secman_auth|localStorage|sessionStorage|withCredentials|authenticated\" src/frontend/src/middleware.ts src/frontend/src/utils src/backendng/src/main/kotlin/com/secman/controller/AuthController.kt src/backendng/src/main/kotlin/com/secman/service/AuthCookieService.kt", workdir:"/Users/flake/sources/misc/secman", yield_time_ms:1000, max_output_tokens:16000}],
  ["SCRIPTS", {cmd:"for p in $(rg -o '\\./scripts/[A-Za-z0-9_./-]+\\.sh' CLAUDE.md | sort -u); do if [ ! -f \"${p#./}\" ]; then echo \"MISSING $p\"; fi; done; find src/backendng/src/main/kotlin/com/secman -maxdepth 1 -type d -print | sort; find src/frontend/src -maxdepth 1 -type d -print | sort; find src/cli/src/main/kotlin/com/secman/cli -maxdepth 1 -type d -print | sort; find src/shared/src/main/kotlin/com/secman/crowdstrike -maxdepth 1 -type d -print | sort; find src/relay -maxdepth 1 -type d -print | sort", workdir:"/Users/flake/sources/misc/secman", yield_time_ms:1000, max_output_tokens:12000}],
  ["CLIENT_CALLS", {cmd:"rg -n '/api/[A-Za-z0-9/_.{}$-]+|\"/mcp\"|X-MCP-User-Email|tools/call' extensions -g '*.py' -g '!**/.venv/**' -g '!**/.git/**' -g '!**/node_modules/**'", workdir:"/Users/flake/sources/misc/secman", yield_time_ms:1000, max_output_tokens:30000}],
  ["RELAY", {cmd:"rg -n '/api/v1/|/ingest/v1/' extensions/secman_app_ios -g '*.swift'; rg -n 'RELAY_SNAPSHOT_SCHEMA_VERSION|RELAY_CONTROL_SCHEMA_VERSION' src/backendng/src/main/kotlin/com/secman/relay/RelayDtos.kt; rg -n 'relaySupportedSnapshotSchemaVersion|relaySupportedControlSchemaVersion' extensions/secman_app_ios -g '*.swift'; rg -n 'SECTION_POLICIES|SectionPolicy|section' src/backendng/src/main/kotlin/com/secman/relay/RelaySnapshotBuilder.kt | head -80; rg -n 'api/v1|ingest/v1' src/relay/internal/api", workdir:"/Users/flake/sources/misc/secman", yield_time_ms:1000, max_output_tokens:20000}],
  ["CONTROLLERS", {cmd:"rg -n '@Controller|@(Get|Post|Put|Delete)\\(' src/backendng/src/main/kotlin/com/secman/controller/{AuthController,VulnerabilityController,AssetController,ScanController,IntegrationResultController,IntegrationScannerController}.kt", workdir:"/Users/flake/sources/misc/secman", yield_time_ms:1000, max_output_tokens:22000}]
];
const rs = await Promise.all(calls.map(async ([label,args]) => [label, await tools.exec_command(args)]));
for (const [label,r] of rs) { text(`===${label}===\n${r.output}`); }

